import type { Tone } from './depth';

// Curated, tone-appropriate vocabulary. Content is generated by recombining
// these banks with a seeded RNG (see feedGenerator.ts / portalTemplates.ts),
// so output is varied but never reads as noise — every combination was
// written to make sense together within its tone.

