export const PORTAL_ACTIONS: Record<Tone, string[]> = {
  light: ['Open', 'Poke', 'Peek into', 'Unwrap', 'Bounce into', 'Say hi to'],
  mid: ['Step into', 'Listen to', 'Follow', 'Approach', 'Wait near', 'Read'],
  deep: ['Enter', 'Descend into', 'Face', 'Answer', 'Sit with', 'Open, carefully,'],
};

export function titleFor(tone: Tone, rng: () => number): string {
  const action = PORTAL_ACTIONS[tone][Math.floor(rng() * PORTAL_ACTIONS[tone].length)];
  const adj = ADJECTIVES[tone][Math.floor(rng() * ADJECTIVES[tone].length)];
  const noun = NOUNS[tone][Math.floor(rng() * NOUNS[tone].length)];
  return `${action} the ${adj} ${noun}`;
}

const BLURB_TEMPLATES: Record<Tone, ((adj: string, noun: string) => string)[]> = {
  light: [
    (adj, noun) => `A ${adj} ${noun} appeared out of nowhere. It's giving off great energy.`,
    (adj, noun) => `Someone left a ${adj} ${noun} here for whoever scrolled far enough.`,
    (adj, noun) => `This ${noun} is extremely ${adj} and wants to be clicked.`,
  ],
  mid: [
    (adj, noun) => `There's a ${adj} ${noun} here. Nobody's sure how long it's been.`,
    (adj, noun) => `A ${noun}, ${adj} and unattended. It might be worth a look.`,
    (adj, noun) => `You keep passing ${adj} ${noun}s like this. This one feels different.`,
  ],
  deep: [
    (adj, noun) => `A ${adj} ${noun} waits here. It has been waiting for a while.`,
    (adj, noun) => `This ${noun} is ${adj}. It knows you're reading this.`,
    (adj, noun) => `Something about this ${noun} is ${adj} in a way that's hard to name.`,
  ],
};

export function blurbFor(tone: Tone, rng: () => number): string {
  const adj = ADJECTIVES[tone][Math.floor(rng() * ADJECTIVES[tone].length)];
  const noun = NOUNS[tone][Math.floor(rng() * NOUNS[tone].length)];
  const template = BLURB_TEMPLATES[tone][Math.floor(rng() * BLURB_TEMPLATES[tone].length)];
  return template(adj, noun);
}

export function whisperFor(tone: Tone, rng: () => number): string {
  const lines = WHISPER_LINES[tone];
  return lines[Math.floor(rng() * lines.length)];
}
